165|function parseLibrary(json: unknown): Library {
166|  if (!isRecord(json)) throw new Error("library must be an object");
167|  if (json.version !== 1) throw new Error(`library version must be 1, got ${String(json.version)}`);
168|  if (!Array.isArray(json.styles)) throw new Error("library styles must be an array");
169|  if (!Array.isArray(json.soundtracks)) throw new Error("library soundtracks must be an array");
170|  if (!Array.isArray(json.playlists ?? [])) throw new Error("library playlists must be an array");
171|  const soundtracks = json.soundtracks.map((entry, i) => {
172|    if (!isRecord(entry)) throw new Error(`library soundtrack ${i} must be an object`);
173|    const credit = optString(entry, "credit", `library soundtrack ${entry.id ?? i}`);
174|    return {
175|      id: reqString(entry, "id", `library soundtrack ${i}`),
176|      name: reqString(entry, "name", `library soundtrack ${i}`),
177|      style: reqString(entry, "style", `library soundtrack ${i}`),
