180|  });
181|  if (!isRecord(json.entries)) throw new Error("library entries must be an object");
182|  const entries: Record<string, LibraryEntry> = {};
183|  for (const [trackId, raw] of Object.entries(json.entries)) {
184|    if (!isRecord(raw)) throw new Error(`library entry ${trackId} must be an object`);
185|    const what = `library entry ${trackId}`;
