201|    if (gainDb !== undefined) {
202|      if (typeof gainDb !== "number" || !Number.isFinite(gainDb) || gainDb < -24 || gainDb > 12) {
203|        throw new Error(`track ${id} gainDb must be a finite number in -24..12`);
204|      }
205|      gain = gainDb;
206|    }
207|    let end: number | undefined;
208|    if (endSec !== undefined) {
209|      if (typeof endSec !== "number" || !Number.isFinite(endSec)) {
210|        throw new Error(`track ${id} endSec must be a finite number`);
211|      }
212|      if (endSec <= start) {
213|        throw new Error(`track ${id} endSec must be above startSec`);
214|      }
215|      // durationSec rounds to 1 decimal, so allow that slack on the end.
216|      if (endSec - start > durationSec + 0.051) {
217|        throw new Error(`track ${id} endSec must not pass startSec + durationSec`);
218|      }
219|      end = endSec;
220|    }
221|    let loops = true;
222|    if (loop !== undefined) {
223|      if (typeof loop !== "boolean") throw new Error(`track ${id} loop must be a boolean`);
224|      loops = loop;
225|    }
226|    let only = false;
227|    if (playlistOnly !== undefined) {
228|      if (typeof playlistOnly !== "boolean") {
229|        throw new Error(`track ${id} playlistOnly must be a boolean`);
230|      }
231|      only = playlistOnly;
232|    }
233|    let trackSource: TrackSource | undefined;
234|    if (source !== undefined) {
235|      if (!isOneOf(source, SOURCES)) {
236|        throw new Error(`track ${id} source must be generated, jamendo, or recording`);
237|      }
238|      trackSource = source;
239|    }
240|    const credit: { artist?: string; composer?: string; license?: string; attribution?: string } = {};
241|    const pairs = [
242|      ["artist", artist],
243|      ["composer", composer],
244|      ["license", license],
245|      ["attribution", attribution],
246|    ] as const;
247|    for (const [key, value] of pairs) {
248|      if (value === undefined) continue;
249|      if (!isNonEmptyString(value)) throw new Error(`track ${id} ${key} must be a non-empty string`);
250|      credit[key] = value;
251|    }
252|    if (sourceUrl !== undefined && (typeof sourceUrl !== "string" || !sourceUrl.startsWith("https://"))) {
253|      throw new Error(`track ${id} sourceUrl must be an https URL`);
254|    }
255|    return {
256|      id,
257|      src,
258|      title,
259|      playlistOnly: only,
260|      emotion,
261|      vector,
262|      intensity,
263|      tempo,
264|      durationSec,
265|      startSec: start,
266|      gainDb: gain,
267|      ...(end === undefined ? {} : { endSec: end }),
268|      loop: loops,
269|      soundtrack,
270|      style,
271|      ...credit,
272|      ...(trackSource === undefined ? {} : { source: trackSource }),
273|      ...(sourceUrl === undefined ? {} : { sourceUrl }),
274|    };
275|  }
