237|      }
238|      trackSource = source;
239|    }
240|    const credit: { artist?: string; composer?: string; license?: string; attribution?: string } = {};
241|    const pairs = [
242|      ["artist", artist],
243|      ["composer", composer],
244|      ["license", license],
245|      ["attribution", attribution],
246|    ] as const;
247|    for (const [key, value] of pairs) {
248|      if (value === undefined) continue;
249|      if (!isNonEmptyString(value)) throw new Error(`track ${id} ${key} must be a non-empty string`);
250|      credit[key] = value;
251|    }
252|    if (sourceUrl !== undefined && (typeof sourceUrl !== "string" || !sourceUrl.startsWith("https://"))) {
253|      throw new Error(`track ${id} sourceUrl must be an https URL`);
254|    }
255|    return {
256|      id,
257|      src,
258|      title,
259|      playlistOnly: only,
260|      emotion,
261|      vector,
262|      intensity,
263|      tempo,
264|      durationSec,
265|      startSec: start,
266|      gainDb: gain,
267|      ...(end === undefined ? {} : { endSec: end }),
